    capture: /^incoming\/[a-zA-Z0-9-]{1,80}$/,
    stream: /^streams\/[a-zA-Z0-9-]{1,80}\/$/,
    restore: /^snapshots\/[a-zA-Z0-9-]{1,80}$/,
