    key: string,
    streamKey?: string,
    options: StageOptions = {},
  ): Promise<ReplayableObject> {
    const operationSignal = abortSignal(options);
    return this.#stage(key, streamKey, options, operationSignal);
  }
  async #stage(
    key: string,
    streamKey: string | undefined,
    options: StageOptions,
    operationSignal: AbortSignal,
  ): Promise<ReplayableObject> {
